"""Optical centre of a one-line text-only centred carrier, in rendered pixels."""
JS=r'''let chip_alignment=[];for(let e of [...(root.matches('.chip,.tag,.kick,.mark')?[root]:[]),...root.querySelectorAll('.chip,.tag,.kick,.mark,.pill>.parts')]){let st=getComputedStyle(e);let painted=z=>{let q=getComputedStyle(z);let hit=rgba(q.backgroundColor)[3]>0||q.backgroundImage!=='none'||['Top','Right','Bottom','Left'].some(k=>parseFloat(q['border'+k+'Width'])>0&&q['border'+k+'Style']!=='none'&&rgba(q['border'+k+'Color'])[3]>0);for(let ps of ['::before','::after']){let ss=getComputedStyle(z,ps);if(ss.content!=='none'&&(rgba(ss.backgroundColor)[3]>0||ss.backgroundImage!=='none'))hit=true}return hit};let flowIcon=['::before','::after'].some(ps=>{let q=getComputedStyle(e,ps);return q.content!=="none"&&q.position!=="absolute"&&q.position!=="fixed"&&parseFloat(q.width)>0&&parseFloat(q.height)>0&&(rgba(q.backgroundColor)[3]>0||q.backgroundImage!=="none")});if(flowIcon)continue;if(!painted(e)&&!(e.matches('.pill>.parts')&&painted(e.parentElement)))continue;if(!e.textContent.trim()||e.querySelector('.icon,[data-ph],svg')||!['flex','inline-flex','grid','inline-grid'].includes(st.display)||st.alignItems!=='center'||!['center','normal'].includes(st.justifyContent))continue;let ns=[];let wt=document.createTreeWalker(e,NodeFilter.SHOW_TEXT);while(wt.nextNode())if(wt.currentNode.textContent.trim())ns.push(wt.currentNode);if(ns.length!==1)continue;let node=ns[0],pa=node.parentElement,s=getComputedStyle(pa);let rr=document.createRange();rr.selectNodeContents(node);let rs=[...rr.getClientRects()].filter(r=>r.width>.1&&r.height>.1);if(rs.length!==1)continue;let r=rs[0],b=e.getBoundingClientRect(),c=document.createElement('canvas').getContext('2d');c.font=s.fontStyle+' '+s.fontWeight+' '+s.fontSize+' '+s.fontFamily;if('letterSpacing'in c)c.letterSpacing=s.letterSpacing;let m=c.measureText(node.textContent);let ax=r.left+(m.actualBoundingBoxRight-m.actualBoundingBoxLeft)/2,ay=r.top+(m.fontBoundingBoxAscent||0)+(m.actualBoundingBoxDescent-m.actualBoundingBoxAscent)/2;let dx=ax-(b.left+b.width/2),dy=ay-(b.top+b.height/2);if(Math.abs(dx)>2.05||Math.abs(dy)>2.05)chip_alignment.push({text:node.textContent.trim(),carrier:e.className,dx,dy,rect:[b.x,b.y,b.width,b.height],glyphCentre:[ax,ay]})}'''
